import json
import sys
from pathlib import Path

def sample_qas(in_file, out_file, num_qas=10):
    with open(in_file, 'r', encoding='utf-8') as f:
        data = json.load(f)
    out = {'data': []}
    total_qas = 0
    for article in data['data']:
        art_copy = {'title': article.get('title', ''), 'paragraphs': []}
        for para in article['paragraphs']:
            para_copy = {'context': para['context'], 'qas': []}
            for qa in para['qas']:
                if total_qas < num_qas:
                    para_copy['qas'].append(qa)
                    total_qas += 1
                if total_qas >= num_qas:
                    break
            if para_copy['qas']:
                art_copy['paragraphs'].append(para_copy)
            if total_qas >= num_qas:
                break
        if art_copy['paragraphs']:
            out['data'].append(art_copy)
        if total_qas >= num_qas:
            break
    with open(out_file, 'w', encoding='utf-8') as f:
        json.dump(out, f)

if __name__ == '__main__':
    if len(sys.argv) != 4:
        print('Usage: python sample_squad.py [input.json] [output.json] [num_qas]')
        sys.exit(1)
    sample_qas(sys.argv[1], sys.argv[2], int(sys.argv[3]))

