import json
def read_jsonl(file_path, n_lines=10):
    # Read the first 10 lines from the JSONL file
    data = []
    with open(file_path, 'r') as file:
        for i in range(n_lines):
            line = file.readline()
            if line:
                json_obj = json.loads(line.strip())
                data.append(json_obj)
            else:
                break
    return data

